540→  /**
541→   * Subscribe to task integration events and forward user-facing updates.
542→   */
543→  private setupTaskProgressListeners(): void {
544→    const integration = getTaskIntegration();
545→
546→    // Mapping to track last progress message per session to avoid noise
547→    const lastProgressUpdate = new Map<string, number>();
548→    const THROTTLE_MS = pipeline.progressThrottle; // Minimum time between general progress updates
549→
550→    // Helper to resolve user ID from session ID
551→    const resolveTarget = async (sessionId: string): Promise<string | null> => {
552→      if (!sessionId) return null;
553→      // If it looks like a JID, use it directly (legacy/direct support)
554→      if (sessionId.includes('@c.us') || sessionId.includes('@g.us')) return sessionId;
555→
556→      // Otherwise, resolve via SessionManager
557→      try {
558→        const { getSessionManager } = await import('../session/manager.js');
559→        const manager = await getSessionManager();
560→        const session = await manager.getSessionById(sessionId);
561→        return session ? session.userId : null;
562→      } catch (_err) {
563→        logger.warn('Failed to resolve session owner', { sessionId });
564→        return null;
565→      }
566→    };
567→
568→    // Codex emits structured JSONL lifecycle events on stdout. These are
569→    // useful for internal telemetry but should never be forwarded verbatim
570→    // to WhatsApp users.
571→    const isStructuredHarnessEventLine = (raw: string): boolean => {
572→      const line = raw.trim();
573→      if (!line.startsWith('{') || !line.endsWith('}')) return false;
574→      try {
575→        const parsed = JSON.parse(line) as { type?: unknown; item?: { type?: unknown } };
576→        const type = typeof parsed.type === 'string' ? parsed.type : '';
577→        if (
578→          type.startsWith('thread.') ||
579→          type.startsWith('turn.') ||
580→          type.startsWith('item.')
581→        ) {
582→          return true;
583→        }
584→        const itemType = typeof parsed.item?.type === 'string' ? parsed.item.type : '';
585→        return itemType === 'command_execution' || itemType === 'reasoning' || itemType === 'file_change';
586→      } catch {
587→        return false;
588→      }
589→    };
590→
591→    integration.on('task:progress', async (event: TaskProgressEvent) => {
592→      const { sessionId, message } = event;
593→      if (!sessionId || !message) return;
594→      if (isStructuredHarnessEventLine(message)) return;
595→
596→      const targetId = await resolveTarget(sessionId);
597→      if (!targetId) return;
598→
599→      const now = Date.now();
600→      const lastUpdate = lastProgressUpdate.get(sessionId) || 0;
601→
602→      // Always send priority patterns, throttle others
603→      const isPriority = /starting|done|complete|failed|error|waiting/i.test(message);
604→
605→      if (isPriority || (now - lastUpdate > THROTTLE_MS)) {
606→        try {
607→          const chunks = await composeTaskProgressMessages(message, sessionId);
608→          for (const chunk of chunks) {
609→            const sentMsg = await this.client.sendMessage(targetId, `🐕 ${chunk}`);
610→            if (sentMsg && sentMsg.id && sentMsg.id._serialized) {
611→              this.trackBotMessage(sentMsg.id._serialized);
612→            }
613→          }
614→          lastProgressUpdate.set(sessionId, now);
615→        } catch (error) {
616→          logger.error('Failed to send progress message', error);
617→        }
618→      }
619→    });
620→
621→    integration.on('task:file_op', async (event: TaskFileOpEvent) => {
622→      const { sessionId, operation, path } = event;
623→      if (!sessionId || !operation || !path) return;
624→
625→      const targetId = await resolveTarget(sessionId);
626→      if (!targetId) return;
627→
628→      try {
629→        const chunks = composeTaskFileOpMessages(operation, path);
630→        for (const chunk of chunks) {
631→          const sentMsg = await this.client.sendMessage(targetId, `🐕 ${chunk}`);
632→          if (sentMsg && sentMsg.id && sentMsg.id._serialized) {
633→            this.trackBotMessage(sentMsg.id._serialized);
634→          }
635→        }
636→      } catch (error) {
637→        logger.error('Failed to send file_op message', error);
638→      }
639→    });
640→
641→    integration.on('task:question', async (event: TaskQuestionEvent) => {
642→      const { sessionId, question } = event;
643→      if (!sessionId || !question) return;
644→
645→      const targetId = await resolveTarget(sessionId);
646→      if (!targetId) return;
647→
648→      try {
649→        const chunks = composeTaskQuestionMessages(question);
650→        for (const chunk of chunks) {
651→          const sentMsg = await this.client.sendMessage(targetId, `🐕 ${chunk}`);
652→          if (sentMsg && sentMsg.id && sentMsg.id._serialized) {
653→            this.trackBotMessage(sentMsg.id._serialized);
654→          }
655→        }
656→      } catch (error) {
657→        logger.error('Failed to send task question', error);
658→      }
659→    });
660→  }
