701→  /**
702→   * Process one inbound message through auth, rate limiting, validation, and handler execution.
703→   */
704→  private async handleIncomingMessage(message: Message, isThreadReply: boolean = false): Promise<void> {
705→    const senderId = message.from;
706→    // eslint-disable-next-line @typescript-eslint/no-explicit-any -- whatsapp-web.js Message.author not in type defs
707→    const participantId = (message as any).author; // Group message author
708→    const messageBody = message.body;
709→
710→    // SECURITY GATE 1: Validate authorization
711→    // For thread replies, we skip the @fetch trigger check but still verify identity
712→    if (isThreadReply) {
713→      // For thread replies, verify owner OR trusted whitelist member (no @fetch required)
714→      const isGroup = senderId.endsWith('@g.us');
715→      const checkId = isGroup ? participantId : senderId;
716→      if (!checkId) return;
717→      if (!this.securityGate.isOwnerMessage(senderId, participantId) &&
718→        !this.securityGate.getWhitelist()?.has(checkId.replace(/@(c|g|s)\.us$/, '').replace(/\D/g, '') || '')) {
719→        return;
720→      }
721→    } else {
722→      // Normal flow: require @fetch trigger + (owner OR trusted)
723→      if (!this.securityGate.isAuthorized(senderId, participantId, messageBody)) {
724→        return;
725→      }
726→    }
727→
728→    // Strip the @fetch trigger from the message (if present)
729→    const command = this.securityGate.stripTrigger(messageBody);
730→
731→    // SECURITY GATE 2: Rate limiting
732→    const rateLimitId = participantId || senderId;
733→    const sessionUserId = await this.resolveCanonicalSessionUserId(message, senderId, participantId);
734→    if (!(await this.rateLimiter.isAllowed(rateLimitId))) {
735→      await message.reply('⏳ Slow down! You\'re sending too many requests. Please wait a moment.');
736→      return;
737→    }
738→
739→    // SECURITY GATE 3: Input validation
740→    const validation = validateInput(command);
741→    if (!validation.valid) {
742→      logger.warn(`Invalid input from owner: ${validation.error}`);
743→      await message.reply(`❌ ${validation.error}`);
744→      return;
745→    }
746→
747→    logger.message(`Received: "${validation.sanitized.substring(0, 40)}${validation.sanitized.length > 40 ? '...' : ''}"`);
748→
749→    try {
750→      let firstMessageSent = false;
751→
752→      // Determine prefix for different media types
753→      let mediaPrefix = '';
754→      if (message.type === 'ptt' || message.type === 'audio') {
755→        mediaPrefix = `🎤 I heard: "${validation.sanitized}"\n\n`;
756→      } else if (message.type === 'image') {
757→        mediaPrefix = `🖼️ I see an image!\n\n`;
758→        // Optional: you could extract the summary from the analysis here if desired
759→      }
760→
761→      // Process through agentic handler
762→      const responses = await handleMessage(
763→        sessionUserId,
764→        validation.sanitized,
765→        async (text) => {
766→          let output = text;
767→          if (!firstMessageSent && mediaPrefix) {
768→            output = mediaPrefix + output;
769→            firstMessageSent = true;
770→          }
771→          const sentMsg = await message.reply(output);
772→          if (sentMsg && sentMsg.id && sentMsg.id._serialized) {
773→            this.trackBotMessage(sentMsg.id._serialized);
774→          }
775→        }
776→      );
777→
778→      // Send all response messages
779→      for (let i = 0; i < responses.length; i++) {
780→        let response = responses[i];
781→
782→        // Prepend media info prefix if it was a voice note or image and we haven't sent the prefix yet
783→        if (!firstMessageSent && mediaPrefix) {
784→          response = mediaPrefix + response;
785→          firstMessageSent = true; // Mark as sent so subsequent responses don't get it
786→        }
787→
788→        const sentMsg = await message.reply(response);
789→        if (sentMsg && sentMsg.id && sentMsg.id._serialized) {
790→          this.trackBotMessage(sentMsg.id._serialized);
791→        }
792→        logger.success(`Reply sent (${response.length} chars)`);
793→
794→        // Small delay between messages to avoid rate limiting
795→        if (responses.length > 1 && i < responses.length - 1) {
796→          await new Promise(resolve => setTimeout(resolve, 500));
797→        }
798→      }
799→    } catch (error) {
800→      logger.error('Failed to process message', error);
801→      await message.reply('❌ Sorry, I encountered an error processing your request.');
802→    }
803→  }
