805→  /**
806→   * Resolve a stable per-user session identifier.
807→   *
808→   * Prefer phone-number JIDs (e.g. `15551234567@c.us`) so sessions don't bind
809→   * to opaque WhatsApp LID identifiers (`...@lid`) when a number is available.
810→   */
811→  private async resolveCanonicalSessionUserId(
812→    message: Message,
813→    senderId: string,
814→    participantId: string | undefined,
815→  ): Promise<string> {
816→    const isGroup = senderId.endsWith('@g.us');
817→    const baseId = (isGroup ? (participantId || senderId) : senderId) || senderId;
818→
819→    // Already canonical.
820→    if (baseId.endsWith('@c.us')) {
821→      return baseId;
822→    }
823→
824→    try {
825→      const contact = await message.getContact();
826→      // whatsapp-web.js commonly exposes `number` and `id._serialized`.
827→      // eslint-disable-next-line @typescript-eslint/no-explicit-any -- runtime shape varies by WA account mode
828→      const contactAny = contact as any;
829→      const number = String(contactAny?.number || '').replace(/\D/g, '');
830→      if (number.length >= 10 && number.length <= 15) {
831→        return `${number}@c.us`;
832→      }
833→
834→      const serialized = String(contactAny?.id?._serialized || '');
835→      if (serialized.endsWith('@c.us')) {
836→        return serialized;
837→      }
838→    } catch {
839→      // Ignore contact lookup failures and continue with fallback normalization.
840→    }
841→
842→    const atIndex = baseId.indexOf('@');
843→    const local = atIndex >= 0 ? baseId.slice(0, atIndex) : baseId;
844→    const digits = local.replace(/\D/g, '');
845→    if (digits.length >= 10 && digits.length <= 15) {
846→      return `${digits}@c.us`;
847→    }
848→
849→    return baseId;
850→  }
